#!/bin/bash
# Lock guard for the served résumé and cover letter PDFs.
# Rewritten 2026-11-19: the PDFs are now the typeset final PDFs (house format v2, two pages,
# made by ~/DataLake/scripts/typeset_resume.py and build_letter.py from the vault sources),
# copied in as files/resume.pdf and files/cover-letter.pdf. resume.html is regenerated by hand
# from the same markdown. This script no longer prints the PDF from the page; it checks what is served.
# History: on 8/26 the served PDF drifted from the page and kept retired claims for five weeks.
set -euo pipefail
cd "$(dirname "$0")"
~/DataLake/.venv/bin/python - <<'PY'
import fitz, sys
bad = False
for f, pages in (("files/resume.pdf", 2), ("files/cover-letter.pdf", 1)):
    d = fitz.open(f); t = "".join(p.get_text() for p in d)
    if d.page_count != pages: print(f"FAIL: {f} has {d.page_count} page(s), expected {pages}"); bad = True
    banned = ["Shira Goodman", "November 2025", "Nov 2025", "nearly seven", "exited profitably", "Exited profitably",
              "run by HUD", "hackathon run by", "head of global operations", "—"]
    hits = [b for b in banned if b in t]
    if hits: print(f"FAIL: banned string(s) in {f}:", hits); bad = True
    if f.endswith("resume.pdf") and "October 2025" not in t: print("FAIL: October 2025 missing from", f); bad = True
if bad: sys.exit(1)
print("lock guard: PASS")
PY
